/// <summary>
/// AllowBackOrders OnModified
/// </summary>
/// <param name="sender">Form Data source</param>
/// <param name="e">Form data source event</param>
[FormDataFieldEventHandler(formDataFieldStr(MetItemSiteSettingsSetup, MetItemSiteSettingsSetup, AllowBackOrders), FormDataFieldEventType::Modified)]
public static void AllowBackOrders_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource  MetItemSiteSettingsSetup_ds   = sender.datasource();
    MetItemSiteSettingsSetup  metItemSiteSettingsSetup      = MetItemSiteSettingsSetup_ds.cursor();
    DialogButton    dialogButton;
    
    dialogButton = Box::yesNo(strFmt("@MET:AllowBackOrdersItemSiteWarning",
                              metItemSiteSettingsSetup.AllowBackOrders ? METConstants::enable : METConstants::disable), 
                              DialogButton::Yes);
        
    if (dialogButton == DialogButton::No)
    {
        metItemSiteSettingsSetup.AllowBackOrders = !metItemSiteSettingsSetup.AllowBackOrders;
    }           
}
